import { mkdirSync, readFileSync, rmSync } from 'node:fs';
import { basename, join } from 'node:path';

import multipart from '@fastify/multipart';
import sensible from '@fastify/sensible';
import Database from 'better-sqlite3';
import Fastify from 'fastify';
import sharp from 'sharp';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { migrate } from '../db';
import { AVATARS_DIR, MAX_ATTACHMENT_BYTES, MAX_AVATAR_BYTES } from '../runtimeConfig';
import { ForumStore } from '../store';
import { createAccessHelpers } from '../utils/access';
import { registerProfileRoutes } from './profileRoutes';

import type { FastifyInstance } from 'fastify';

const AUTH_TOKEN = 'avatar-test-token';

// Stable, independently encoded Apache-2.0 fixtures from lovell/sharp v0.35.3
// (PNG/JPEG/GIF) and GoogleChromeLabs/squoosh (WebP). Keeping the encoded bytes
// here ensures route inputs are not generated by the Sharp runtime under test.
const AVATAR_FIXTURES = [
  {
    sourceFormat: 'png',
    mimetype: 'image/png',
    base64: 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAE0lEQVQIHWP8eyaPgYGBCYiBAAAbTQI7Cm2dtQAAAABJRU5ErkJggg==',
  },
  {
    sourceFormat: 'jpeg',
    mimetype: 'image/jpeg',
    base64:
      '',
  },
  {
    sourceFormat: 'gif',
    mimetype: 'image/gif',
    base64: 'R0lGODlhAgABAIAAAGVlZf///yH5BAEAAAEALAAAAAACAAEAAAICRAoAOw==',
  },
  {
    sourceFormat: 'webp',
    mimetype: 'image/webp',
    base64: 'UklGRh4AAABXRUJQVlA4TBEAAAAvAAAAAAfQ//73v/+BiOh/AAA=',
  },
] as const;

function multipartPayload(file: Buffer, mimetype: string): { body: Buffer; contentType: string } {
  const boundary = `forum-avatar-${Date.now().toString(36)}`;
  const head = Buffer.from(
    [
      `--${boundary}`,
      `Content-Disposition: form-data; name="file"; filename="avatar"`,
      `Content-Type: ${mimetype}`,
      '',
      '',
    ].join('\r\n')
  );
  const tail = Buffer.from(`\r\n--${boundary}--\r\n`);
  return {
    body: Buffer.concat([head, file, tail]),
    contentType: `multipart/form-data; boundary=${boundary}`,
  };
}

describe('profile avatar image processing', () => {
  let app: FastifyInstance;
  let db: Database.Database;
  let store: ForumStore;
  let identityId: string;
  const savedAvatars = new Set<string>();

  beforeEach(async () => {
    mkdirSync(AVATARS_DIR, { recursive: true });
    db = new Database(':memory:');
    migrate(db);
    store = new ForumStore(db);
    const identity = store.createIdentityWithPassword('Avatar Owner', 'avatar-owner', 'pw-hash', 'human');
    identityId = identity.id;
    store.createAuthSession(AUTH_TOKEN, identity.id);

    app = Fastify({ logger: false });
    await app.register(sensible);
    await app.register(multipart, { limits: { fileSize: MAX_ATTACHMENT_BYTES } });
    registerProfileRoutes({ app, store, access: createAccessHelpers(app, store) });
    await app.ready();
  });

  afterEach(async () => {
    await app.close();
    db.close();
    for (const path of savedAvatars) rmSync(path, { force: true });
    savedAvatars.clear();
  });

  async function upload(file: Buffer, mimetype: string) {
    const multipart = multipartPayload(file, mimetype);
    const response = await app.inject({
      method: 'POST',
      url: `/identities/${identityId}/avatar`,
      headers: {
        authorization: `Bearer ${AUTH_TOKEN}`,
        'content-type': multipart.contentType,
      },
      payload: multipart.body,
    });

    const avatarUrl = (response.json() as { avatarUrl?: string }).avatarUrl;
    if (avatarUrl) savedAvatars.add(join(AVATARS_DIR, basename(avatarUrl)));
    return response;
  }

  it.each(AVATAR_FIXTURES)(
    'converts an independently encoded $sourceFormat upload to a 200px JPEG avatar',
    async ({ mimetype, base64 }) => {
      const response = await upload(Buffer.from(base64, 'base64'), mimetype);

      expect(response.statusCode).toBe(200);
      const body = response.json() as { avatarUrl: string };
      expect(body.avatarUrl).toMatch(new RegExp(`^/uploads/avatars/${identityId}_\\d+\\.jpg$`));
      expect(store.getIdentity(identityId)?.avatar_url).toBe(body.avatarUrl);

      const outputPath = join(AVATARS_DIR, basename(body.avatarUrl));
      const output = readFileSync(outputPath);
      // Assert the output container independently before asking Sharp to decode it.
      expect([...output.subarray(0, 3)]).toEqual([0xff, 0xd8, 0xff]);
      expect([...output.subarray(-2)]).toEqual([0xff, 0xd9]);

      const metadata = await sharp(output).metadata();
      expect(metadata).toMatchObject({ format: 'jpeg', width: 200, height: 200 });
    }
  );

  it('rejects malformed bytes presented as an allowed image type', async () => {
    const response = await upload(Buffer.from('not actually a PNG'), 'image/png');

    expect(response.statusCode).toBe(400);
    expect(response.json().message).toMatch(/unsupported image format|invalid|corrupt/i);
    expect(store.getIdentity(identityId)?.avatar_url).toBeNull();
  });

  it('rejects an allowed-type upload above the avatar byte limit before image decoding', async () => {
    const response = await upload(Buffer.alloc(MAX_AVATAR_BYTES + 1, 0x61), 'image/png');

    expect(response.statusCode).toBe(400);
    expect(response.json().message).toBe(
      `Avatar file too large. Max ${Math.floor(MAX_AVATAR_BYTES / (1024 * 1024))}MB.`
    );
    expect(store.getIdentity(identityId)?.avatar_url).toBeNull();
  });
});
